values
  ('en:baking-powder', array['Baking powder']::text[], 'A raising-agent blend, usually a carbonate plus an acid salt.', 'Releases gas so baked goods rise.', 'Baking powder is a safe, common baking ingredient.', 'low', array[]::text[], array[]::text[], array['cakes', 'biscuits', 'self-raising products', 'batters']::text[], '[{"name": "USDA FoodData Central", "url": "https://fdc.nal.usda.gov/"}]'::jsonb, 'high', '2026-07', '1.1'),
  ('en:barley', array['Barley', 'Pearl barley']::text[], 'A cereal grain.', 'A staple grain used in foods and to make malt.', 'Barley is a safe whole grain; it contains gluten.', 'low', array['people with coeliac disease or who avoid gluten']::text[], array[]::text[], array['soups', 'cereals', 'malt', 'bread']::text[], '[{"name": "USDA FoodData Central", "url": "https://fdc.nal.usda.gov/"}]'::jsonb, 'high', '2026-07', '1.1'),
  ('en:butter', array['Butter']::text[], 'A dairy fat churned from cream.', 'Adds flavour and richness and shapes texture in baking.', 'Butter is safe to eat; it is high in saturated fat, which health bodies suggest limiting.', 'low', array['people with a milk allergy', 'people advised to limit saturated fat']::text[], array[]::text[], array['baked goods', 'spreads', 'sauces', 'pastries']::text[], '[{"name": "WHO guideline: saturated and trans-fatty acid intake, 2023", "url": "https://www.who.int/publications/i/item/9789240073630"}, {"name": "USDA FoodData Central", "url": "https://fdc.nal.usda.gov/"}]'::jsonb, 'high', '2026-07', '1.1'),
  ('en:calcium', array['Calcium', 'Added calcium', 'Calcium (fortified)']::text[], 'A mineral added to fortify foods.', 'Fortifies foods such as plant drinks and flour with calcium.', 'Added calcium is safe at the levels used to fortify foods; calcium is an essential mineral for bones.', 'low', array[]::text[], array[]::text[], array['plant drinks', 'fortified flour', 'breakfast cereals']::text[], '[{"name": "WHO guidelines on food fortification with micronutrients", "url": "https://www.who.int/publications/i/item/9241594012"}, {"name": "EFSA Dietary Reference Values for nutrients", "url": "https://www.efsa.europa.eu/en/topics/topic/dietary-reference-values"}]'::jsonb, 'high', '2026-07', '1.1'),
  ('en:cheese', array['Cheese', 'Cheddar', 'Mozzarella']::text[], 'A dairy food made by curdling milk.', 'Adds flavour, protein, and texture.', 'Cheese is a safe, nutritious dairy food for most people; it is a milk product and can be high in salt and saturated fat.', 'low', array['people with a milk allergy', 'people advised to limit sodium or saturated fat']::text[], array[]::text[], array['ready meals', 'sandwiches', 'pizza', 'snacks']::text[], '[{"name": "USDA FoodData Central", "url": "https://fdc.nal.usda.gov/"}]'::jsonb, 'high', '2026-07', '1.1'),
  ('en:cocoa', array['Cocoa', 'Cocoa mass', 'Cocoa solids', 'Cocoa powder']::text[], 'Solids from the cocoa bean.', 'Gives chocolate flavour and colour.', 'Cocoa is a safe food ingredient; it naturally contains a small amount of caffeine.', 'low', array[]::text[], array[]::text[], array['chocolate', 'baked goods', 'drinks', 'desserts']::text[], '[{"name": "USDA FoodData Central", "url": "https://fdc.nal.usda.gov/"}]'::jsonb, 'high', '2026-07', '1.1'),
  ('en:cocoa-butter', array['Cocoa butter']::text[], 'The natural fat of the cocoa bean.', 'Gives chocolate its smooth texture and melt.', 'Cocoa butter is safe to eat and is high in saturated fat.', 'low', array[]::text[], array[]::text[], array['chocolate', 'confectionery', 'coatings']::text[], '[{"name": "USDA FoodData Central", "url": "https://fdc.nal.usda.gov/"}]'::jsonb, 'high', '2026-07', '1.1'),
  ('en:coconut-oil', array['Coconut oil']::text[], 'An oil pressed from coconut flesh.', 'Adds texture and stays solid at room temperature.', 'Coconut oil is safe to eat; it is high in saturated fat, which health bodies suggest limiting.', 'low', array['people advised to limit saturated fat']::text[], array['Claims that coconut oil is a uniquely healthy fat are not well supported; it is still high in saturated fat']::text[], array['baked goods', 'spreads', 'confectionery', 'cooking oils']::text[], '[{"name": "WHO guideline: saturated and trans-fatty acid intake, 2023", "url": "https://www.who.int/publications/i/item/9789240073630"}, {"name": "USDA FoodData Central", "url": "https://fdc.nal.usda.gov/"}]'::jsonb, 'high', '2026-07', '1.1'),
  ('en:cream', array['Cream', 'Double cream', 'Single cream']::text[], 'The fat-rich part of milk.', 'Adds richness and texture.', 'Cream is a safe dairy food; it is a milk product and is high in saturated fat.', 'low', array['people with a milk allergy', 'people advised to limit saturated fat']::text[], array[]::text[], array['desserts', 'sauces', 'baked goods', 'dairy products']::text[], '[{"name": "WHO guideline: saturated and trans-fatty acid intake, 2023", "url": "https://www.who.int/publications/i/item/9789240073630"}, {"name": "USDA FoodData Central", "url": "https://fdc.nal.usda.gov/"}]'::jsonb, 'high', '2026-07', '1.1'),
  ('en:dextrose', array['Dextrose', 'Glucose', 'Grape sugar']::text[], 'A simple sugar (glucose), often made from maize.', 'Adds sweetness and energy and is used in baking and sports foods.', 'Dextrose (glucose) is a form of sugar; the WHO advice on limiting free sugars applies to it.', 'low', array['people managing diabetes may want to watch total sugars']::text[], array[]::text[], array['sports drinks', 'sweets', 'baked goods', 'processed foods']::text[], '[{"name": "WHO guideline: sugars intake for adults and children, 2015", "url": "https://www.who.int/publications/i/item/9789241549028"}, {"name": "USDA FoodData Central", "url": "https://fdc.nal.usda.gov/"}]'::jsonb, 'high', '2026-07', '1.1'),
  ('en:e100', array['Curcumin', 'E100']::text[], 'A colour used in food.', 'Adds or restores colour so a product looks consistent.', 'Natural turmeric color; EFSA set an ADI and typical dietary exposure stays within it.', 'low', array[]::text[], array[]::text[], array['sweets', 'soft drinks', 'coloured snacks', 'desserts']::text[], '[{"name": "EFSA re-evaluation of curcumin (E100), 2010", "url": "https://www.efsa.europa.eu/en/efsajournal/pub/1679"}]'::jsonb, 'high', '2026-07', '1.1'),
  ('en:e101', array['Riboflavin (vitamin B2)', 'E101']::text[], 'A colour used in food.', 'Adds or restores colour so a product looks consistent.', 'A B vitamin used as a yellow color; EFSA found no safety concern at reported uses.', 'low', array[]::text[], array[]::text[], array['sweets', 'soft drinks', 'coloured snacks', 'desserts']::text[], '[{"name": "EFSA re-evaluation of riboflavins (E101), 2013", "url": "https://www.efsa.europa.eu/en/efsajournal/pub/3357"}]'::jsonb, 'high', '2026-07', '1.1'),
  ('en:e102', array['Tartrazine', 'E102']::text[], 'A colour used in food.', 'Adds or restores colour so a product looks consistent.', 'Azo color with an EFSA ADI; foods containing it in the EU must carry a note about possible effects on activity and attention in children.', 'moderate', array[]::text[], array[]::text[], array['sweets', 'soft drinks', 'coloured snacks', 'desserts']::text[], '[{"name": "EFSA re-evaluation of tartrazine (E102), 2009", "url": "https://www.efsa.europa.eu/en/efsajournal/pub/1331"}, {"name": "EU Regulation 1333/2008 Annex V (labelling of certain colours)", "url": "https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=CELEX%3A32008R1333"}]'::jsonb, 'high', '2026-07', '1.1'),
  ('en:e104', array['Quinoline yellow', 'E104']::text[], 'A colour used in food.', 'Adds or restores colour so a product looks consistent.', 'EFSA lowered its ADI in 2009 and EU labelling rules for certain colors apply; not authorized for food in the US.', 'moderate', array[]::text[], array[]::text[], array['sweets', 'soft drinks', 'coloured snacks', 'desserts']::text[], '[{"name": "EFSA re-evaluation of quinoline yellow (E104), 2009", "url": "https://www.efsa.europa.eu/en/efsajournal/pub/1329"}]'::jsonb, 'high', '2026-07', '1.1'),
  ('en:e110', array['Sunset yellow FCF', 'E110']::text[], 'A colour used in food.', 'Adds or restores colour so a product looks consistent.', 'Azo color; EFSA revised its ADI in 2014 and EU child-activity labelling rules apply.', 'moderate', array[]::text[], array[]::text[], array['sweets', 'soft drinks', 'coloured snacks', 'desserts']::text[], '[{"name": "EFSA refined exposure assessment of sunset yellow (E110), 2014", "url": "https://www.efsa.europa.eu/en/efsajournal/pub/3765"}]'::jsonb, 'high', '2026-07', '1.1'),
  ('en:e120', array['Cochineal / carminic acid (carmine)', 'E120']::text[], 'A food acid.', 'Adjusts acidity or adds a tart taste; can also help preserve.', 'EFSA maintained the ADI in 2015; rare hypersensitivity reactions are documented, so people with known sensitivity may want to check for it.', 'moderate', array['people with a known carmine or cochineal sensitivity']::text[], array[]::text[], array['soft drinks', 'sweets', 'preserves', 'sauces']::text[], '[{"name": "EFSA re-evaluation of cochineal, carminic acid, carmines (E120), 2015", "url": "https://www.efsa.europa.eu/en/efsajournal/pub/4288"}]'::jsonb, 'high', '2026-07', '1.1'),
  ('en:e122', array['Azorubine / carmoisine', 'E122']::text[], 'A colour used in food.', 'Adds or restores colour so a product looks consistent.', 'Azo color with an EFSA ADI; EU child-activity labelling rules apply and it is not authorized in the US.', 'moderate', array[]::text[], array[]::text[], array['sweets', 'soft drinks', 'coloured snacks', 'desserts']::text[], '[{"name": "EFSA re-evaluation of azorubine/carmoisine (E122), 2009", "url": "https://www.efsa.europa.eu/en/efsajournal/pub/1332"}]'::jsonb, 'high', '2026-07', '1.1'),
  ('en:e124', array['Ponceau 4R', 'E124']::text[], 'A food additive.', 'Serves a technical role such as texture, colour, or shelf life.', 'EFSA lowered its ADI in 2009; EU child-activity labelling rules apply and it is not authorized in the US.', 'moderate', array[]::text[], array[]::text[], array['a range of packaged foods']::text[], '[{"name": "EFSA re-evaluation of Ponceau 4R (E124), 2009", "url": "https://www.efsa.europa.eu/en/efsajournal/pub/1328"}]'::jsonb, 'high', '2026-07', '1.1'),
  ('en:e127', array['Erythrosine (Red 3)', 'E127']::text[], 'A food additive.', 'Serves a technical role such as texture, colour, or shelf life.', 'The US FDA revoked its authorization for foods in January 2025 based on findings in laboratory animals; it remains permitted in limited uses elsewhere.', 'higher', array[]::text[], array[]::text[], array['a range of packaged foods']::text[], '[{"name": "FDA order revoking authorization of FD&C Red No. 3, 2025", "url": "https://www.fda.gov/food/hfp-constituent-updates/fda-revoke-authorization-use-red-no-3-food-and-ingested-drugs"}, {"name": "EFSA re-evaluation of erythrosine (E127), 2011", "url": "https://www.efsa.europa.eu/en/efsajournal/pub/1854"}]'::jsonb, 'high', '2026-07', '1.1'),
  ('en:e129', array['Allura red AC', 'E129']::text[], 'A colour used in food.', 'Adds or restores colour so a product looks consistent.', 'Azo color with an EFSA ADI; EU child-activity labelling rules apply.', 'moderate', array[]::text[], array[]::text[], array['sweets', 'soft drinks', 'coloured snacks', 'desserts']::text[], '[{"name": "EFSA re-evaluation of Allura Red AC (E129), 2009", "url": "https://www.efsa.europa.eu/en/efsajournal/pub/1327"}]'::jsonb, 'high', '2026-07', '1.1'),
  ('en:e133', array['Brilliant blue FCF', 'E133']::text[], 'A food additive.', 'Serves a technical role such as texture, colour, or shelf life.', 'EFSA set an ADI and estimated dietary exposure stays below it for all population groups.', 'low', array[]::text[], array[]::text[], array['a range of packaged foods']::text[], '[{"name": "EFSA re-evaluation of Brilliant Blue FCF (E133), 2010", "url": "https://www.efsa.europa.eu/en/efsajournal/pub/1853"}]'::jsonb, 'high', '2026-07', '1.1'),
  ('en:e140', array['Chlorophylls', 'E140']::text[], 'A colour used in food.', 'Adds or restores colour so a product looks consistent.', 'A green plant-derived colour; EFSA re-evaluated it as a food colour and placed no numeric intake limit on it.', 'low', array[]::text[], array[]::text[], array['sweets', 'soft drinks', 'coloured snacks', 'desserts']::text[], '[{"name": "EFSA re-evaluation of chlorophylls (E140) as a food additive", "url": "https://www.efsa.europa.eu/en/topics/topic/food-additives"}]'::jsonb, 'high', '2026-07', '1.1'),
  ('en:e1412', array['Distarch phosphate', 'E1412']::text[], 'A modified starch.', 'A starch treated so it thickens or stays stable during cooking, freezing, or storage.', 'A modified starch used as a thickener and stabiliser; EFSA re-evaluated the modified starches and found no safety concern at reported uses.', 'low', array[]::text[], array[]::text[], array['sauces', 'soups', 'ready meals', 'desserts']::text[], '[{"name": "EFSA re-evaluation of modified starches (E1404-E1451) as food additives", "url": "https://www.efsa.europa.eu/en/topics/topic/food-additives"}]'::jsonb, 'high', '2026-07', '1.1'),
