  ('en:e150a', array['Plain caramel', 'E150a']::text[], 'A plain caramel colour (made by heating carbohydrates).', 'Adds a brown colour.', 'A plain caramel colour made by heating carbohydrates; EFSA set a group ADI for caramel colours that plain caramel stays within.', 'low', array[]::text[], array[]::text[], array['sweets', 'soft drinks', 'coloured snacks', 'desserts']::text[], '[{"name": "EFSA re-evaluation of caramel colours (E150a-d), 2011", "url": "https://www.efsa.europa.eu/en/efsajournal/pub/2004"}]'::jsonb, 'high', '2026-07', '1.1'),
  ('en:e150c', array['Ammonia caramel', 'E150c']::text[], 'An ammonia caramel colour.', 'Adds a brown colour, common in savoury foods and some drinks.', 'An ammonia caramel colour; EFSA set a group ADI for caramel colours and estimated that high consumers of some products can approach it.', 'moderate', array[]::text[], array[]::text[], array['sweets', 'soft drinks', 'coloured snacks', 'desserts']::text[], '[{"name": "EFSA re-evaluation of caramel colours (E150a-d), 2011", "url": "https://www.efsa.europa.eu/en/efsajournal/pub/2004"}]'::jsonb, 'high', '2026-07', '1.1'),
  ('en:e150d', array['Sulphite ammonia caramel', 'E150d']::text[], 'A caramel colour (the sulphite ammonia type).', 'Adds a brown colour, most familiar from colas.', 'EFSA set a group ADI for caramel colors; the 4-MEI byproduct is monitored and intake by high consumers can approach the ADI.', 'moderate', array[]::text[], array[]::text[], array['soft drinks', 'sauces', 'baked goods', 'cured foods']::text[], '[{"name": "EFSA re-evaluation of caramel colours (E150a-d), 2011", "url": "https://www.efsa.europa.eu/en/efsajournal/pub/2004"}]'::jsonb, 'high', '2026-07', '1.1'),
  ('en:e153', array['Vegetable carbon', 'E153']::text[], 'A colour used in food.', 'Adds or restores colour so a product looks consistent.', 'A black colour made from charred plant material; EFSA found reported food uses to be of no safety concern.', 'low', array[]::text[], array[]::text[], array['sweets', 'soft drinks', 'coloured snacks', 'desserts']::text[], '[{"name": "EFSA re-evaluation of vegetable carbon (E153) as a food additive", "url": "https://www.efsa.europa.eu/en/topics/topic/food-additives"}]'::jsonb, 'high', '2026-07', '1.1'),
  ('en:e160a', array['Carotenes', 'E160a']::text[], 'A colour used in food.', 'Adds or restores colour so a product looks consistent.', 'Plant-derived orange pigments (provitamin A); EFSA found reported food uses of mixed carotenes to be of no safety concern.', 'low', array[]::text[], array[]::text[], array['sweets', 'soft drinks', 'coloured snacks', 'desserts']::text[], '[{"name": "EFSA re-evaluation of mixed carotenes (E160a), 2012", "url": "https://www.efsa.europa.eu/en/efsajournal/pub/2593"}]'::jsonb, 'high', '2026-07', '1.1'),
  ('en:e160b', array['Annatto extracts', 'E160b']::text[], 'A colour used in food.', 'Adds or restores colour so a product looks consistent.', 'Seed-derived color; EFSA set updated ADIs in 2016 and exposure estimates stay within them.', 'low', array[]::text[], array[]::text[], array['sweets', 'soft drinks', 'coloured snacks', 'desserts']::text[], '[{"name": "EFSA safety assessment of annatto extracts (E160b), 2016", "url": "https://www.efsa.europa.eu/en/efsajournal/pub/4544"}]'::jsonb, 'high', '2026-07', '1.1'),
