  ('en:e160e', array['Beta-apo-8''-carotenal', 'E160e']::text[], 'A colour used in food.', 'Adds or restores colour so a product looks consistent.', 'An orange carotenoid colour; EFSA set an ADI and estimated dietary exposure stays within it.', 'low', array[]::text[], array[]::text[], array['sweets', 'soft drinks', 'coloured snacks', 'desserts']::text[], '[{"name": "EFSA re-evaluation of beta-apo-8''-carotenal (E160e) as a food additive", "url": "https://www.efsa.europa.eu/en/topics/topic/food-additives"}]'::jsonb, 'high', '2026-07', '1.1'),
  ('en:e162', array['Beetroot red (betanin)', 'E162']::text[], 'A colour used in food.', 'Adds or restores colour so a product looks consistent.', 'A red colour from beetroot; EFSA found no safety concern and placed no numeric intake limit on it.', 'low', array[]::text[], array[]::text[], array['sweets', 'soft drinks', 'coloured snacks', 'desserts']::text[], '[{"name": "EFSA re-evaluation of beetroot red (E162) as a food additive", "url": "https://www.efsa.europa.eu/en/topics/topic/food-additives"}]'::jsonb, 'high', '2026-07', '1.1'),
  ('en:e163', array['Anthocyanins', 'E163']::text[], 'A colour used in food.', 'Adds or restores colour so a product looks consistent.', 'Purple-red plant colours from fruit and vegetables; EFSA found reported food uses to be of no safety concern.', 'low', array[]::text[], array[]::text[], array['sweets', 'soft drinks', 'coloured snacks', 'desserts']::text[], '[{"name": "EFSA re-evaluation of anthocyanins (E163) as a food additive", "url": "https://www.efsa.europa.eu/en/topics/topic/food-additives"}]'::jsonb, 'high', '2026-07', '1.1'),
  ('en:e170', array['Calcium carbonate', 'E170']::text[], 'A mineral used in food.', 'Adds firmness, adjusts acidity, or provides a mineral.', 'A mineral (chalk) also used as a calcium source; EFSA found no safety concern at reported uses.', 'low', array[]::text[], array[]::text[], array['supplemented foods', 'baked goods', 'canned vegetables']::text[], '[{"name": "EFSA re-evaluation of calcium carbonate (E170), 2011", "url": "https://www.efsa.europa.eu/en/efsajournal/pub/2318"}]'::jsonb, 'high', '2026-07', '1.1'),
  ('en:e171', array['Titanium dioxide', 'E171']::text[], 'A white mineral colour (titanium dioxide).', 'Makes foods and coatings look bright white or opaque.', 'EFSA concluded in 2021 that genotoxicity could not be ruled out and the EU withdrew its food authorization in 2022; it remains permitted in some other jurisdictions, including the US.', 'higher', array[]::text[], array[]::text[], array['a range of packaged foods']::text[], '[{"name": "EFSA safety assessment of titanium dioxide (E171), 2021", "url": "https://www.efsa.europa.eu/en/news/titanium-dioxide-e171-no-longer-considered-safe-when-used-food-additive"}, {"name": "EU Regulation 2022/63 (removal of E171 from authorized additives)", "url": "https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=CELEX%3A32022R0063"}]'::jsonb, 'high', '2026-07', '1.1'),
  ('en:e172', array['Iron oxides and hydroxides', 'E172']::text[], 'Iron-oxide mineral colours (yellow, red, black).', 'Add yellow, red, brown, or black colour.', 'Mineral iron-based colours; EFSA set an ADI and estimated dietary exposure stays within it.', 'low', array[]::text[], array[]::text[], array['sweets', 'soft drinks', 'coloured snacks', 'desserts']::text[], '[{"name": "EFSA re-evaluation of iron oxides and hydroxides (E172) as a food additive", "url": "https://www.efsa.europa.eu/en/topics/topic/food-additives"}]'::jsonb, 'high', '2026-07', '1.1'),
  ('en:e200', array['Sorbic acid', 'E200']::text[], 'A preservative.', 'Helps food keep longer by slowing spoilage from microbes.', 'A common preservative; EFSA set a revised group ADI for sorbic acid and sorbates in 2019 and typical exposure stays within it.', 'low', array[]::text[], array[]::text[], array['soft drinks', 'sauces', 'baked goods', 'cured foods']::text[], '[{"name": "EFSA revised group ADI for sorbic acid and potassium sorbate (E200, E202), 2019", "url": "https://www.efsa.europa.eu/en/efsajournal/pub/5625"}]'::jsonb, 'high', '2026-07', '1.1'),
  ('en:e202', array['Potassium sorbate', 'E202']::text[], 'A preservative.', 'Helps food keep longer by slowing spoilage from microbes.', 'Common preservative; EFSA set a revised group ADI in 2019 and typical exposure stays within it.', 'low', array[]::text[], array[]::text[], array['soft drinks', 'sauces', 'baked goods', 'cured foods']::text[], '[{"name": "EFSA revised group ADI for sorbic acid and potassium sorbate (E200, E202), 2019", "url": "https://www.efsa.europa.eu/en/efsajournal/pub/5625"}]'::jsonb, 'high', '2026-07', '1.1'),
  ('en:e203', array['Calcium sorbate', 'E203']::text[], 'A preservative.', 'Helps food keep longer by slowing spoilage from microbes.', 'A preservative in the sorbate group; EFSA set a revised group ADI in 2019 that typical exposure stays within.', 'low', array[]::text[], array[]::text[], array['soft drinks', 'sauces', 'baked goods', 'cured foods']::text[], '[{"name": "EFSA revised group ADI for sorbic acid and potassium sorbate (E200, E202), 2019", "url": "https://www.efsa.europa.eu/en/efsajournal/pub/5625"}]'::jsonb, 'high', '2026-07', '1.1'),
  ('en:e210', array['Benzoic acid', 'E210']::text[], 'A preservative.', 'Helps food keep longer by slowing spoilage from microbes.', 'A preservative with an EFSA group ADI; intake by children who consume many soft drinks can approach the ADI.', 'moderate', array[]::text[], array[]::text[], array['soft drinks', 'sauces', 'baked goods', 'cured foods']::text[], '[{"name": "EFSA re-evaluation of benzoic acid and benzoates (E210-E213), 2016", "url": "https://www.efsa.europa.eu/en/efsajournal/pub/4433"}]'::jsonb, 'high', '2026-07', '1.1'),
  ('en:e211', array['Sodium benzoate', 'E211']::text[], 'A preservative.', 'Helps food keep longer by slowing spoilage from microbes.', 'Preservative with an EFSA group ADI; intake by children who consume many soft drinks can approach the ADI, and benzene can form in some drinks that also contain vitamin C.', 'moderate', array[]::text[], array['The benzene concern applies only to some drinks that also contain vitamin C, not to sodium benzoate in general']::text[], array['soft drinks', 'sauces', 'baked goods', 'cured foods']::text[], '[{"name": "EFSA re-evaluation of benzoic acid and benzoates (E210-E213), 2016", "url": "https://www.efsa.europa.eu/en/efsajournal/pub/4433"}]'::jsonb, 'high', '2026-07', '1.1'),
  ('en:e212', array['Potassium benzoate', 'E212']::text[], 'A preservative.', 'Helps food keep longer by slowing spoilage from microbes.', 'A preservative in the benzoate group with an EFSA group ADI; intake by high consumers of soft drinks can approach the ADI.', 'moderate', array[]::text[], array[]::text[], array['soft drinks', 'sauces', 'baked goods', 'cured foods']::text[], '[{"name": "EFSA re-evaluation of benzoic acid and benzoates (E210-E213), 2016", "url": "https://www.efsa.europa.eu/en/efsajournal/pub/4433"}]'::jsonb, 'high', '2026-07', '1.1'),
  ('en:e220', array['Sulphur dioxide', 'E220']::text[], 'Sulphur dioxide, a preservative and antioxidant.', 'Helps food keep longer by slowing spoilage from microbes.', 'EFSA''s 2022 re-evaluation could not confirm the safety of the previous ADI due to data gaps, and some people are sensitive to sulphites; it must be declared as an allergen in the EU and US.', 'moderate', array['people who are sensitive to sulphites, including some people with asthma']::text[], array[]::text[], array['soft drinks', 'sauces', 'baked goods', 'cured foods']::text[], '[{"name": "EFSA re-evaluation of sulphur dioxide and sulphites (E220-E228), 2022", "url": "https://www.efsa.europa.eu/en/efsajournal/pub/7594"}]'::jsonb, 'high', '2026-07', '1.1'),
  ('en:e223', array['Sodium metabisulphite', 'E223']::text[], 'An antioxidant.', 'Slows fats and oils from going rancid, protecting flavour.', 'A sulphite preservative and antioxidant; EFSA''s 2022 re-evaluation could not confirm the previous ADI due to data gaps, and it must be declared as an allergen in the EU and US.', 'moderate', array[]::text[], array[]::text[], array['oils', 'snacks', 'spreads', 'processed meats']::text[], '[{"name": "EFSA re-evaluation of sulphur dioxide and sulphites (E220-E228), 2022", "url": "https://www.efsa.europa.eu/en/efsajournal/pub/7594"}]'::jsonb, 'high', '2026-07', '1.1'),
  ('en:e224', array['Potassium metabisulphite', 'E224']::text[], 'An antioxidant.', 'Slows fats and oils from going rancid, protecting flavour.', 'A sulphite preservative and antioxidant; EFSA''s 2022 re-evaluation could not confirm the previous ADI due to data gaps, and it must be declared as an allergen in the EU and US.', 'moderate', array[]::text[], array[]::text[], array['oils', 'snacks', 'spreads', 'processed meats']::text[], '[{"name": "EFSA re-evaluation of sulphur dioxide and sulphites (E220-E228), 2022", "url": "https://www.efsa.europa.eu/en/efsajournal/pub/7594"}]'::jsonb, 'high', '2026-07', '1.1'),
  ('en:e234', array['Nisin', 'E234']::text[], 'A preservative.', 'Helps food keep longer by slowing spoilage from microbes.', 'A preservative produced by fermentation; EFSA re-evaluated it and set an ADI that estimated exposure stays within.', 'low', array[]::text[], array[]::text[], array['soft drinks', 'sauces', 'baked goods', 'cured foods']::text[], '[{"name": "EFSA re-evaluation of nisin (E234) as a food additive", "url": "https://www.efsa.europa.eu/en/topics/topic/food-additives"}]'::jsonb, 'high', '2026-07', '1.1'),
  ('en:e235', array['Natamycin', 'E235']::text[], 'A preservative.', 'Helps food keep longer by slowing spoilage from microbes.', 'A preservative used on the surface of cheese and cured meats; EFSA set an ADI that estimated exposure stays within.', 'low', array[]::text[], array[]::text[], array['soft drinks', 'sauces', 'baked goods', 'cured foods']::text[], '[{"name": "EFSA re-evaluation of natamycin (E235) as a food additive", "url": "https://www.efsa.europa.eu/en/topics/topic/food-additives"}]'::jsonb, 'high', '2026-07', '1.1'),
  ('en:e249', array['Potassium nitrite', 'E249']::text[], 'A curing salt (potassium nitrite) for processed meats.', 'Helps food keep longer by slowing spoilage from microbes.', 'Curing salt for processed meats; EFSA''s 2023 assessment found dietary exposure to nitrosamines, which can form from nitrites, raises a health concern across age groups.', 'higher', array[]::text[], array[]::text[], array['soft drinks', 'sauces', 'baked goods', 'cured foods']::text[], '[{"name": "EFSA opinion on nitrosamines in food, 2023", "url": "https://www.efsa.europa.eu/en/news/nitrosamines-food-raise-health-concern"}, {"name": "IARC Monographs vol. 114 (processed meat), 2015", "url": "https://monographs.iarc.who.int/list-of-classifications"}]'::jsonb, 'high', '2026-07', '1.1'),
  ('en:e250', array['Sodium nitrite', 'E250']::text[], 'A curing salt (sodium nitrite) for processed meats.', 'Helps food keep longer by slowing spoilage from microbes.', 'Curing salt for processed meats; EFSA''s 2023 assessment found dietary exposure to nitrosamines, which can form from nitrites, raises a health concern, and the EU tightened permitted levels in 2023.', 'higher', array[]::text[], array[]::text[], array['soft drinks', 'sauces', 'baked goods', 'cured foods']::text[], '[{"name": "EFSA opinion on nitrosamines in food, 2023", "url": "https://www.efsa.europa.eu/en/news/nitrosamines-food-raise-health-concern"}, {"name": "EU Regulation 2023/2108 (lower limits for nitrites and nitrates)", "url": "https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=CELEX%3A32023R2108"}]'::jsonb, 'high', '2026-07', '1.1'),
  ('en:e251', array['Sodium nitrate', 'E251']::text[], 'A preservative.', 'Helps food keep longer by slowing spoilage from microbes.', 'Can convert to nitrite in the body; EFSA re-confirmed the ADI in 2017 but the EU lowered permitted use levels in 2023 as a precaution around nitrosamine formation.', 'moderate', array[]::text[], array[]::text[], array['soft drinks', 'sauces', 'baked goods', 'cured foods']::text[], '[{"name": "EFSA re-evaluation of sodium and potassium nitrate (E251-E252), 2017", "url": "https://www.efsa.europa.eu/en/efsajournal/pub/4787"}, {"name": "EU Regulation 2023/2108 (lower limits for nitrites and nitrates)", "url": "https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=CELEX%3A32023R2108"}]'::jsonb, 'high', '2026-07', '1.1'),
  ('en:e260', array['Acetic acid', 'E260']::text[], 'A food acid.', 'Adjusts acidity or adds a tart taste; can also help preserve.', 'The acid in vinegar; regulators place no numeric intake limit on it.', 'low', array[]::text[], array[]::text[], array['soft drinks', 'sweets', 'preserves', 'sauces']::text[], '[{"name": "JECFA evaluation of acetic acid (ADI not limited)", "url": "https://apps.who.int/food-additives-contaminants-jecfa-database/"}]'::jsonb, 'high', '2026-07', '1.1'),
  ('en:e262', array['Sodium acetates', 'E262']::text[], 'A food acid.', 'Adjusts acidity or adds a tart taste; can also help preserve.', 'Salts of acetic acid used to regulate acidity; regulators place no numeric intake limit on them.', 'low', array[]::text[], array[]::text[], array['soft drinks', 'sweets', 'preserves', 'sauces']::text[], '[{"name": "JECFA evaluation of sodium acetates (ADI not limited)", "url": "https://apps.who.int/food-additives-contaminants-jecfa-database/"}]'::jsonb, 'high', '2026-07', '1.1'),
