  ('en:e280', array['Propionic acid', 'E280']::text[], 'A preservative.', 'Helps food keep longer by slowing spoilage from microbes.', 'A preservative that slows mould in baked goods; EFSA found no safety concern and placed no numeric intake limit on it.', 'low', array[]::text[], array[]::text[], array['soft drinks', 'sauces', 'baked goods', 'cured foods']::text[], '[{"name": "EFSA re-evaluation of propionic acid and propionates (E280-E283) as food additives", "url": "https://www.efsa.europa.eu/en/topics/topic/food-additives"}]'::jsonb, 'high', '2026-07', '1.1'),
