  ('en:e300', array['Ascorbic acid (vitamin C)', 'E300']::text[], 'An antioxidant.', 'Slows fats and oils from going rancid, protecting flavour.', 'Vitamin C used as an antioxidant; EFSA found no safety concern and no need for a numeric ADI.', 'low', array[]::text[], array[]::text[], array['oils', 'snacks', 'spreads', 'processed meats']::text[], '[{"name": "EFSA re-evaluation of ascorbic acid (E300-E302), 2015", "url": "https://www.efsa.europa.eu/en/efsajournal/pub/4087"}]'::jsonb, 'high', '2026-07', '1.1'),
