  ('en:e310', array['Propyl gallate', 'E310']::text[], 'An antioxidant.', 'Slows fats and oils from going rancid, protecting flavour.', 'A synthetic antioxidant with an EFSA group ADI for gallates; some consumers can approach the group limit.', 'moderate', array[]::text[], array[]::text[], array['oils', 'snacks', 'spreads', 'processed meats']::text[], '[{"name": "EFSA re-evaluation of propyl gallate (E310) as a food additive", "url": "https://www.efsa.europa.eu/en/topics/topic/food-additives"}]'::jsonb, 'high', '2026-07', '1.1'),
  ('en:e320', array['Butylated hydroxyanisole (BHA)', 'E320']::text[], 'An antioxidant.', 'Slows fats and oils from going rancid, protecting flavour.', 'Synthetic antioxidant with an EFSA ADI; IARC classifies it as Group 2B (possibly carcinogenic, based on high-dose animal data) while typical dietary exposure stays below the ADI.', 'moderate', array[]::text[], array['The ''possibly carcinogenic'' label reflects high-dose animal data; typical dietary intake stays below the regulatory limit']::text[], array['oils', 'snacks', 'spreads', 'processed meats']::text[], '[{"name": "EFSA re-evaluation of BHA (E320), 2011", "url": "https://www.efsa.europa.eu/en/efsajournal/pub/2392"}, {"name": "IARC Monographs list of classifications (BHA, Group 2B)", "url": "https://monographs.iarc.who.int/list-of-classifications"}]'::jsonb, 'high', '2026-07', '1.1'),
  ('en:e321', array['Butylated hydroxytoluene (BHT)', 'E321']::text[], 'An antioxidant.', 'Slows fats and oils from going rancid, protecting flavour.', 'Synthetic antioxidant; EFSA set an ADI in 2012 and high consumers can approach it.', 'moderate', array[]::text[], array['IARC and animal-study findings are about high doses; regulators set intake limits well below those levels']::text[], array['oils', 'snacks', 'spreads', 'processed meats']::text[], '[{"name": "EFSA re-evaluation of BHT (E321), 2012", "url": "https://www.efsa.europa.eu/en/efsajournal/pub/2588"}]'::jsonb, 'high', '2026-07', '1.1'),
