  ('en:e340', array['Potassium phosphates', 'E340']::text[], 'A phosphate used as an additive.', 'Regulates acidity, raises baked goods, or holds moisture.', 'Part of the phosphate group for which EFSA set a group intake limit in 2019; high consumers can exceed it.', 'moderate', array[]::text[], array[]::text[], array['colas', 'processed cheese', 'baked goods', 'processed meats']::text[], '[{"name": "EFSA re-evaluation of phosphoric acid and phosphates (E338-E341, E343, E450-E452), 2019", "url": "https://www.efsa.europa.eu/en/efsajournal/pub/5674"}]'::jsonb, 'high', '2026-07', '1.1'),
  ('en:e341', array['Calcium phosphates', 'E341']::text[], 'A phosphate used as an additive.', 'Regulates acidity, raises baked goods, or holds moisture.', 'Part of the phosphate group for which EFSA set a group intake limit in 2019; also used as a raising agent and calcium source, and high consumers can exceed the group limit.', 'moderate', array[]::text[], array[]::text[], array['colas', 'processed cheese', 'baked goods', 'processed meats']::text[], '[{"name": "EFSA re-evaluation of phosphoric acid and phosphates (E338-E341, E343, E450-E452), 2019", "url": "https://www.efsa.europa.eu/en/efsajournal/pub/5674"}]'::jsonb, 'high', '2026-07', '1.1'),
