  ('en:e400', array['Alginic acid', 'E400']::text[], 'A thickener or gelling agent.', 'Thickens or sets the texture of a food.', 'A seaweed-derived thickener and stabiliser; EFSA re-evaluated the alginates and found no safety concern at reported uses.', 'low', array[]::text[], array[]::text[], array['desserts', 'dairy', 'sauces', 'jams']::text[], '[{"name": "EFSA re-evaluation of alginic acid and alginates (E400-E404) as food additives", "url": "https://www.efsa.europa.eu/en/topics/topic/food-additives"}]'::jsonb, 'high', '2026-07', '1.1'),
  ('en:e401', array['Sodium alginate', 'E401']::text[], 'A thickener or gelling agent.', 'Thickens or sets the texture of a food.', 'A seaweed-derived thickener and stabiliser; EFSA found no safety concern at reported uses.', 'low', array[]::text[], array[]::text[], array['desserts', 'dairy', 'sauces', 'jams']::text[], '[{"name": "EFSA re-evaluation of alginic acid and alginates (E400-E404) as food additives", "url": "https://www.efsa.europa.eu/en/topics/topic/food-additives"}]'::jsonb, 'high', '2026-07', '1.1'),
  ('en:e406', array['Agar', 'E406']::text[], 'A thickener or gelling agent.', 'Thickens or sets the texture of a food.', 'Seaweed-derived gelling agent; EFSA found no safety concern at reported uses.', 'low', array[]::text[], array[]::text[], array['desserts', 'dairy', 'sauces', 'jams']::text[], '[{"name": "EFSA re-evaluation of agar (E406), 2016", "url": "https://www.efsa.europa.eu/en/efsajournal/pub/4645"}]'::jsonb, 'high', '2026-07', '1.1'),
  ('en:e407', array['Carrageenan', 'E407']::text[], 'A thickener or gelling agent.', 'Thickens or sets the texture of a food.', 'Seaweed-derived thickener; EFSA kept a temporary ADI in 2018 because of data gaps and asked for further studies.', 'moderate', array[]::text[], array['Research on gut effects is ongoing; regulators kept only a temporary intake limit while asking for more studies']::text[], array['desserts', 'dairy', 'sauces', 'jams']::text[], '[{"name": "EFSA re-evaluation of carrageenan (E407), 2018", "url": "https://www.efsa.europa.eu/en/efsajournal/pub/5238"}]'::jsonb, 'high', '2026-07', '1.1'),
  ('en:e410', array['Locust bean gum', 'E410']::text[], 'A thickener or gelling agent.', 'Thickens or sets the texture of a food.', 'Carob-seed thickener; EFSA found no safety concern for the general population at reported uses.', 'low', array[]::text[], array[]::text[], array['desserts', 'dairy', 'sauces', 'jams']::text[], '[{"name": "EFSA re-evaluation of locust bean gum (E410), 2017", "url": "https://www.efsa.europa.eu/en/efsajournal/pub/4646"}]'::jsonb, 'high', '2026-07', '1.1'),
