  ('en:e414', array['Gum arabic (acacia gum)', 'E414']::text[], 'A thickener or gelling agent.', 'Thickens or sets the texture of a food.', 'A plant gum (acacia) used as a thickener and stabiliser; regulators place no numeric intake limit on it.', 'low', array[]::text[], array[]::text[], array['desserts', 'dairy', 'sauces', 'jams']::text[], '[{"name": "JECFA evaluation of gum arabic (ADI not specified)", "url": "https://apps.who.int/food-additives-contaminants-jecfa-database/"}]'::jsonb, 'high', '2026-07', '1.1'),
  ('en:e415', array['Xanthan gum', 'E415']::text[], 'A thickener or gelling agent.', 'Thickens or sets the texture of a food.', 'Fermentation-derived thickener; EFSA found no safety concern at reported uses.', 'low', array[]::text[], array[]::text[], array['desserts', 'dairy', 'sauces', 'jams']::text[], '[{"name": "EFSA re-evaluation of xanthan gum (E415), 2017", "url": "https://www.efsa.europa.eu/en/efsajournal/pub/4909"}]'::jsonb, 'high', '2026-07', '1.1'),
  ('en:e418', array['Gellan gum', 'E418']::text[], 'A thickener or gelling agent.', 'Thickens or sets the texture of a food.', 'A fermentation-derived gelling agent and thickener; EFSA found no safety concern at reported uses.', 'low', array[]::text[], array[]::text[], array['desserts', 'dairy', 'sauces', 'jams']::text[], '[{"name": "EFSA re-evaluation of gellan gum (E418) as a food additive", "url": "https://www.efsa.europa.eu/en/topics/topic/food-additives"}]'::jsonb, 'high', '2026-07', '1.1'),
  ('en:e420', array['Sorbitol', 'E420']::text[], 'A sugar alcohol (polyol) used as a sweetener.', 'Adds sweetness and bulk with fewer calories than sugar; also helps hold moisture.', 'A sugar alcohol (polyol) used as a sweetener and humectant; regulators set no numeric ADI, and EU labels note that eating a lot may have a laxative effect.', 'low', array[]::text[], array[]::text[], array['sugar-free sweets', 'chewing gum', 'sugar-free chocolate', 'baked goods']::text[], '[{"name": "EFSA re-evaluation of sorbitol (E420) as a food additive", "url": "https://www.efsa.europa.eu/en/topics/topic/food-additives"}]'::jsonb, 'high', '2026-07', '1.1'),
  ('en:e421', array['Mannitol', 'E421']::text[], 'A sugar alcohol (polyol) used as a sweetener.', 'Adds sweetness and bulk with fewer calories than sugar; also helps hold moisture.', 'A sugar alcohol (polyol) used as a sweetener and anti-caking agent; regulators set no numeric ADI, and EU labels note that eating a lot may have a laxative effect.', 'low', array[]::text[], array[]::text[], array['sugar-free sweets', 'chewing gum', 'sugar-free chocolate', 'baked goods']::text[], '[{"name": "EFSA re-evaluation of mannitol (E421) as a food additive", "url": "https://www.efsa.europa.eu/en/topics/topic/food-additives"}]'::jsonb, 'high', '2026-07', '1.1'),
  ('en:e422', array['Glycerol', 'E422']::text[], 'A humectant.', 'Holds moisture so foods stay soft.', 'Humectant naturally present in fats; EFSA found no safety concern at reported uses.', 'low', array[]::text[], array[]::text[], array['soft baked goods', 'confectionery', 'chewing gum']::text[], '[{"name": "EFSA re-evaluation of glycerol (E422), 2017", "url": "https://www.efsa.europa.eu/en/efsajournal/pub/4720"}]'::jsonb, 'high', '2026-07', '1.1'),
  ('en:e425', array['Konjac', 'E425']::text[], 'A thickener or gelling agent.', 'Thickens or sets the texture of a food.', 'A plant-fibre thickener and gelling agent; EFSA found no safety concern in foods, though it is restricted in jelly mini-cups because of a choking risk.', 'low', array[]::text[], array[]::text[], array['desserts', 'dairy', 'sauces', 'jams']::text[], '[{"name": "EFSA re-evaluation of konjac (E425) as a food additive", "url": "https://www.efsa.europa.eu/en/topics/topic/food-additives"}]'::jsonb, 'high', '2026-07', '1.1'),
  ('en:e433', array['Polysorbate 80', 'E433']::text[], 'An emulsifier.', 'Helps oil and water mix and stay smoothly blended.', 'Emulsifier with an EFSA group ADI; EFSA noted data gaps at re-evaluation and research on emulsifier effects on the gut is ongoing.', 'moderate', array[]::text[], array[]::text[], array['spreads', 'sauces', 'ice cream', 'baked goods']::text[], '[{"name": "EFSA re-evaluation of polysorbates (E432-E436), 2015", "url": "https://www.efsa.europa.eu/en/efsajournal/pub/4152"}]'::jsonb, 'high', '2026-07', '1.1'),
  ('en:e440', array['Pectins', 'E440']::text[], 'A thickener or gelling agent.', 'Thickens or sets the texture of a food.', 'Fruit-derived gelling agent; EFSA found no safety concern and no need for a numeric ADI.', 'low', array[]::text[], array[]::text[], array['desserts', 'dairy', 'sauces', 'jams']::text[], '[{"name": "EFSA re-evaluation of pectins (E440i, E440ii), 2017", "url": "https://www.efsa.europa.eu/en/efsajournal/pub/4866"}]'::jsonb, 'high', '2026-07', '1.1'),
