  ('en:e466', array['Carboxymethylcellulose (cellulose gum)', 'E466']::text[], 'An emulsifier.', 'Helps oil and water mix and stay smoothly blended.', 'EFSA found no safety concern at re-evaluation but noted data gaps, and research on emulsifier effects on the gut microbiome is ongoing.', 'moderate', array[]::text[], array[]::text[], array['spreads', 'sauces', 'ice cream', 'baked goods']::text[], '[{"name": "EFSA re-evaluation of celluloses including E466, 2018", "url": "https://www.efsa.europa.eu/en/efsajournal/pub/5047"}]'::jsonb, 'high', '2026-07', '1.1'),
