  ('en:e475', array['Polyglycerol esters of fatty acids', 'E475']::text[], 'An emulsifier.', 'Helps oil and water mix and stay smoothly blended.', 'An emulsifier; EFSA found no safety concern at reported uses.', 'low', array[]::text[], array[]::text[], array['spreads', 'sauces', 'ice cream', 'baked goods']::text[], '[{"name": "EFSA re-evaluation of polyglycerol esters of fatty acids (E475) as a food additive", "url": "https://www.efsa.europa.eu/en/topics/topic/food-additives"}]'::jsonb, 'high', '2026-07', '1.1'),
  ('en:e476', array['Polyglycerol polyricinoleate (PGPR)', 'E476']::text[], 'An emulsifier.', 'Helps oil and water mix and stay smoothly blended.', 'An emulsifier used to improve the flow of chocolate; EFSA set an ADI that typical use stays within.', 'low', array[]::text[], array[]::text[], array['spreads', 'sauces', 'ice cream', 'baked goods']::text[], '[{"name": "EFSA re-evaluation of polyglycerol polyricinoleate (E476) as a food additive", "url": "https://www.efsa.europa.eu/en/topics/topic/food-additives"}]'::jsonb, 'high', '2026-07', '1.1'),
  ('en:e481', array['Sodium stearoyl-2-lactylate', 'E481']::text[], 'An emulsifier.', 'Helps oil and water mix and stay smoothly blended.', 'An emulsifier and dough conditioner; EFSA set an ADI that estimated exposure stays within.', 'low', array[]::text[], array[]::text[], array['spreads', 'sauces', 'ice cream', 'baked goods']::text[], '[{"name": "EFSA re-evaluation of stearoyl-2-lactylates (E481, E482) as food additives", "url": "https://www.efsa.europa.eu/en/topics/topic/food-additives"}]'::jsonb, 'high', '2026-07', '1.1'),
  ('en:e491', array['Sorbitan monostearate', 'E491']::text[], 'An emulsifier.', 'Helps oil and water mix and stay smoothly blended.', 'An emulsifier; EFSA set a group ADI for sorbitan esters that estimated exposure stays within.', 'low', array[]::text[], array[]::text[], array['spreads', 'sauces', 'ice cream', 'baked goods']::text[], '[{"name": "EFSA re-evaluation of sorbitan esters (E491-E495) as food additives", "url": "https://www.efsa.europa.eu/en/topics/topic/food-additives"}]'::jsonb, 'high', '2026-07', '1.1'),
  ('en:e500', array['Sodium carbonates (baking soda)', 'E500']::text[], 'A raising agent.', 'Releases gas so baked goods rise.', 'Common raising agent; regulators place no numeric intake limit on it.', 'low', array[]::text[], array[]::text[], array['baked goods', 'self-raising flour', 'cake mixes']::text[], '[{"name": "JECFA evaluation of sodium carbonates (ADI not limited)", "url": "https://apps.who.int/food-additives-contaminants-jecfa-database/"}]'::jsonb, 'high', '2026-07', '1.1'),
  ('en:e551', array['Silicon dioxide', 'E551']::text[], 'An anti-caking agent.', 'Keeps powders and granules free-flowing and stops them clumping.', 'An anti-caking agent; EFSA''s 2018 re-evaluation could not fully conclude on safety because of data gaps and asked for more information, while current uses stay under review.', 'moderate', array[]::text[], array[]::text[], array['powdered foods', 'seasonings', 'grated cheese', 'supplements']::text[], '[{"name": "EFSA re-evaluation of silicon dioxide (E551) as a food additive, 2018", "url": "https://www.efsa.europa.eu/en/efsajournal/pub/5088"}]'::jsonb, 'high', '2026-07', '1.1'),
  ('en:e575', array['Glucono-delta-lactone', 'E575']::text[], 'A food acid.', 'Adjusts acidity or adds a tart taste; can also help preserve.', 'A mild acid used as an acidity regulator; regulators place no numeric intake limit on it.', 'low', array[]::text[], array[]::text[], array['soft drinks', 'sweets', 'preserves', 'sauces']::text[], '[{"name": "JECFA evaluation of glucono-delta-lactone (ADI not limited)", "url": "https://apps.who.int/food-additives-contaminants-jecfa-database/"}]'::jsonb, 'high', '2026-07', '1.1'),
  ('en:e620', array['Glutamic acid', 'E620']::text[], 'A flavour enhancer.', 'Boosts the savoury (umami) taste of a food.', 'EFSA set a group ADI for glutamates in 2017 and estimated some population groups can exceed it; glutamate is otherwise a normal component of protein-rich foods.', 'moderate', array[]::text[], array[]::text[], array['savoury snacks', 'seasonings', 'soups', 'ready meals']::text[], '[{"name": "EFSA re-evaluation of glutamic acid and glutamates (E620-E625), 2017", "url": "https://www.efsa.europa.eu/en/efsajournal/pub/4910"}]'::jsonb, 'high', '2026-07', '1.1'),
  ('en:e621', array['Monosodium glutamate (MSG)', 'E621']::text[], 'A flavour enhancer.', 'Boosts the savoury (umami) taste of a food.', 'EFSA set a group ADI for glutamates in 2017 and estimated that some population groups can exceed it; glutamate is otherwise a normal component of protein-rich foods.', 'moderate', array['people advised to limit sodium']::text[], array['A specific ''MSG sensitivity'' has not been confirmed in controlled blind studies', 'Glutamate is a normal part of many everyday protein-rich foods']::text[], array['savoury snacks', 'seasonings', 'soups', 'ready meals']::text[], '[{"name": "EFSA re-evaluation of glutamic acid and glutamates (E620-E625), 2017", "url": "https://www.efsa.europa.eu/en/efsajournal/pub/4910"}]'::jsonb, 'high', '2026-07', '1.1'),
  ('en:e627', array['Disodium guanylate', 'E627']::text[], 'A flavour enhancer.', 'Boosts the savoury (umami) taste of a food.', 'A flavour enhancer usually paired with glutamates; EFSA found no safety concern at reported uses.', 'low', array[]::text[], array[]::text[], array['savoury snacks', 'seasonings', 'soups', 'ready meals']::text[], '[{"name": "EFSA re-evaluation of guanylates and inosinates (E626-E635) as food additives", "url": "https://www.efsa.europa.eu/en/topics/topic/food-additives"}]'::jsonb, 'high', '2026-07', '1.1'),
  ('en:e631', array['Disodium inosinate', 'E631']::text[], 'A flavour enhancer.', 'Boosts the savoury (umami) taste of a food.', 'A flavour enhancer usually paired with glutamates; EFSA found no safety concern at reported uses.', 'low', array[]::text[], array[]::text[], array['savoury snacks', 'seasonings', 'soups', 'ready meals']::text[], '[{"name": "EFSA re-evaluation of guanylates and inosinates (E626-E635) as food additives", "url": "https://www.efsa.europa.eu/en/topics/topic/food-additives"}]'::jsonb, 'high', '2026-07', '1.1'),
  ('en:e635', array['Disodium 5''-ribonucleotides', 'E635']::text[], 'A flavour enhancer.', 'Boosts the savoury (umami) taste of a food.', 'A flavour enhancer (a blend of guanylate and inosinate); EFSA found no safety concern at reported uses.', 'low', array[]::text[], array[]::text[], array['savoury snacks', 'seasonings', 'soups', 'ready meals']::text[], '[{"name": "EFSA re-evaluation of guanylates and inosinates (E626-E635) as food additives", "url": "https://www.efsa.europa.eu/en/topics/topic/food-additives"}]'::jsonb, 'high', '2026-07', '1.1'),
  ('en:e901', array['Beeswax', 'E901']::text[], 'A glazing agent.', 'Forms a shiny protective coating on the surface of a food.', 'A natural wax used as a glazing agent to coat confectionery and fruit; EFSA found no safety concern at reported uses.', 'low', array[]::text[], array[]::text[], array['confectionery', 'chocolate', 'coated fruit', 'supplements']::text[], '[{"name": "EFSA re-evaluation of beeswax (E901) as a food additive", "url": "https://www.efsa.europa.eu/en/topics/topic/food-additives"}]'::jsonb, 'high', '2026-07', '1.1'),
  ('en:e903', array['Carnauba wax', 'E903']::text[], 'A glazing agent.', 'Forms a shiny protective coating on the surface of a food.', 'A plant wax used as a glazing agent; EFSA set an ADI that estimated exposure stays within.', 'low', array[]::text[], array[]::text[], array['confectionery', 'chocolate', 'coated fruit', 'supplements']::text[], '[{"name": "EFSA re-evaluation of carnauba wax (E903) as a food additive", "url": "https://www.efsa.europa.eu/en/topics/topic/food-additives"}]'::jsonb, 'high', '2026-07', '1.1'),
  ('en:e904', array['Shellac', 'E904']::text[], 'A glazing agent.', 'Forms a shiny protective coating on the surface of a food.', 'A resin used as a glazing agent to coat confectionery and fruit; EFSA found no safety concern at reported uses.', 'low', array[]::text[], array[]::text[], array['confectionery', 'chocolate', 'coated fruit', 'supplements']::text[], '[{"name": "EFSA re-evaluation of shellac (E904) as a food additive", "url": "https://www.efsa.europa.eu/en/topics/topic/food-additives"}]'::jsonb, 'high', '2026-07', '1.1'),
  ('en:e924', array['Potassium bromate', 'E924']::text[], 'A flour treatment agent.', 'Was used to strengthen dough and speed bread-making.', 'Flour treatment agent withdrawn from food use in the EU, UK, and Canada; IARC classifies it as Group 2B based on animal studies, and it remains permitted with limits in some jurisdictions.', 'higher', array[]::text[], array['It is already withdrawn from food use in the EU, UK, and Canada; where still allowed, limits apply']::text[], array['some breads and flours in jurisdictions that still allow it']::text[], '[{"name": "IARC Monographs list of classifications (potassium bromate, Group 2B)", "url": "https://monographs.iarc.who.int/list-of-classifications"}]'::jsonb, 'high', '2026-07', '1.1'),
  ('en:e941', array['Nitrogen', 'E941']::text[], 'A food-grade gas.', 'Used to carbonate drinks or to protect packaged food by replacing oxygen.', 'An inert packaging gas used to displace oxygen; regulators place no numeric intake limit on it.', 'low', array[]::text[], array[]::text[], array['fizzy drinks', 'packaged fresh foods', 'bagged snacks']::text[], '[{"name": "JECFA evaluation of nitrogen (ADI not limited)", "url": "https://apps.who.int/food-additives-contaminants-jecfa-database/"}]'::jsonb, 'high', '2026-07', '1.1'),
  ('en:e950', array['Acesulfame K', 'E950']::text[], 'A sweetener used in place of some or all sugar.', 'Adds sweetness with little or no sugar and few or no calories.', 'Sweetener with an EFSA ADI that typical intakes stay within; the WHO''s 2023 guideline advises against relying on non-sugar sweeteners for weight management.', 'moderate', array[]::text[], array['Regulators set an intake limit that typical use stays within; the WHO advice is about relying on sweeteners for weight loss, not about safety at normal intakes']::text[], array['diet soft drinks', 'sugar-free foods', 'tabletop sweeteners']::text[], '[{"name": "EFSA re-evaluation of acesulfame K (E950), 2025", "url": "https://www.efsa.europa.eu/en/topics/topic/sweeteners"}, {"name": "WHO guideline on non-sugar sweeteners, 2023", "url": "https://www.who.int/publications/i/item/9789240073616"}]'::jsonb, 'high', '2026-07', '1.1'),
  ('en:e951', array['Aspartame', 'E951']::text[], 'A sweetener used in place of some or all sugar.', 'Adds sweetness with little or no sugar and few or no calories.', 'EFSA and JECFA maintain an ADI that typical intakes stay well within; IARC classified it Group 2B (limited evidence) in 2023, which JECFA reviewed without changing the ADI.', 'moderate', array['people with phenylketonuria (PKU), because it contains phenylalanine']::text[], array['At normal intakes it has not been shown to cause the health harms sometimes claimed online']::text[], array['diet soft drinks', 'sugar-free foods', 'tabletop sweeteners']::text[], '[{"name": "EFSA full risk assessment of aspartame, 2013", "url": "https://www.efsa.europa.eu/en/topics/topic/aspartame"}, {"name": "IARC/JECFA joint statement on aspartame, 2023", "url": "https://www.who.int/news/item/14-07-2023-aspartame-hazard-and-risk-assessment-results-released"}]'::jsonb, 'high', '2026-07', '1.1'),
  ('en:e953', array['Isomalt', 'E953']::text[], 'A sugar alcohol (polyol) used as a sweetener.', 'Adds sweetness and bulk with fewer calories than sugar; also helps hold moisture.', 'A sugar alcohol (polyol) sweetener; regulators set no numeric ADI, and EU labels note that eating a lot may have a laxative effect.', 'low', array[]::text[], array[]::text[], array['sugar-free sweets', 'chewing gum', 'sugar-free chocolate', 'baked goods']::text[], '[{"name": "EFSA evaluation of isomalt (E953) as a food additive", "url": "https://www.efsa.europa.eu/en/topics/topic/food-additives"}]'::jsonb, 'high', '2026-07', '1.1'),
  ('en:e955', array['Sucralose', 'E955']::text[], 'A sweetener used in place of some or all sugar.', 'Adds sweetness with little or no sugar and few or no calories.', 'Sweetener with a JECFA/EFSA ADI that typical intakes stay within; the WHO''s 2023 guideline advises against relying on non-sugar sweeteners for weight management and EFSA re-evaluation is ongoing.', 'moderate', array[]::text[], array['The WHO advice is about using sweeteners for weight management, not a finding that normal intakes are harmful']::text[], array['diet soft drinks', 'sugar-free foods', 'tabletop sweeteners']::text[], '[{"name": "EFSA sweeteners re-evaluation programme", "url": "https://www.efsa.europa.eu/en/topics/topic/sweeteners"}, {"name": "WHO guideline on non-sugar sweeteners, 2023", "url": "https://www.who.int/publications/i/item/9789240073616"}]'::jsonb, 'high', '2026-07', '1.1'),
  ('en:e960', array['Steviol glycosides (stevia)', 'E960']::text[], 'A sweetener used in place of some or all sugar.', 'Adds sweetness with little or no sugar and few or no calories.', 'A plant-derived (stevia) sweetener; EFSA and JECFA set an ADI that typical intakes stay within.', 'low', array[]::text[], array[]::text[], array['diet soft drinks', 'sugar-free foods', 'tabletop sweeteners']::text[], '[{"name": "EFSA safety of steviol glycosides (E960) as a food additive", "url": "https://www.efsa.europa.eu/en/topics/topic/sweeteners"}]'::jsonb, 'high', '2026-07', '1.1'),
  ('en:e965', array['Maltitol', 'E965']::text[], 'A sugar alcohol (polyol) used as a sweetener.', 'Adds sweetness and bulk with fewer calories than sugar; also helps hold moisture.', 'A sugar alcohol (polyol) sweetener; regulators set no numeric ADI, and EU labels note that eating a lot may have a laxative effect.', 'low', array[]::text[], array[]::text[], array['sugar-free sweets', 'chewing gum', 'sugar-free chocolate', 'baked goods']::text[], '[{"name": "EFSA evaluation of maltitol (E965) as a food additive", "url": "https://www.efsa.europa.eu/en/topics/topic/food-additives"}]'::jsonb, 'high', '2026-07', '1.1'),
  ('en:e966', array['Lactitol', 'E966']::text[], 'A sugar alcohol (polyol) used as a sweetener.', 'Adds sweetness and bulk with fewer calories than sugar; also helps hold moisture.', 'A sugar alcohol (polyol) sweetener; regulators set no numeric ADI, and EU labels note that eating a lot may have a laxative effect.', 'low', array[]::text[], array[]::text[], array['sugar-free sweets', 'chewing gum', 'sugar-free chocolate', 'baked goods']::text[], '[{"name": "EFSA evaluation of lactitol (E966) as a food additive", "url": "https://www.efsa.europa.eu/en/topics/topic/food-additives"}]'::jsonb, 'high', '2026-07', '1.1'),
  ('en:e967', array['Xylitol', 'E967']::text[], 'A sugar alcohol (polyol) used as a sweetener.', 'Adds sweetness and bulk with fewer calories than sugar; also helps hold moisture.', 'A sugar alcohol (polyol) sweetener; regulators set no numeric ADI for people, and EU labels note that eating a lot may have a laxative effect.', 'low', array[]::text[], array[]::text[], array['sugar-free sweets', 'chewing gum', 'sugar-free chocolate', 'baked goods']::text[], '[{"name": "EFSA evaluation of xylitol (E967) as a food additive", "url": "https://www.efsa.europa.eu/en/topics/topic/food-additives"}]'::jsonb, 'high', '2026-07', '1.1'),
  ('en:e968', array['Erythritol', 'E968']::text[], 'A sugar alcohol (polyol) used as a sweetener.', 'Adds sweetness and bulk with fewer calories than sugar; also helps hold moisture.', 'A sugar alcohol (polyol) sweetener that is largely not metabolised; EFSA set no numeric ADI and food authorities consider approved uses acceptable, with research on other effects ongoing.', 'low', array[]::text[], array[]::text[], array['sugar-free sweets', 'chewing gum', 'sugar-free chocolate', 'baked goods']::text[], '[{"name": "EFSA evaluation of erythritol (E968) as a food additive", "url": "https://www.efsa.europa.eu/en/topics/topic/food-additives"}]'::jsonb, 'high', '2026-07', '1.1'),
  ('en:egg', array['Egg', 'Eggs', 'Whole egg', 'Egg white', 'Egg yolk']::text[], 'Hen''s egg or a part of it.', 'Binds, sets, and adds structure, richness, and colour.', 'Eggs are a safe, nutritious food for most people; they are a common allergen.', 'low', array['people with an egg allergy']::text[], array[]::text[], array['baked goods', 'pasta', 'sauces', 'mayonnaise']::text[], '[{"name": "USDA FoodData Central", "url": "https://fdc.nal.usda.gov/"}]'::jsonb, 'high', '2026-07', '1.1'),
  ('en:folic-acid', array['Folic acid', 'Folate', 'Vitamin B9']::text[], 'A B vitamin (folate) added to foods.', 'Fortifies foods to help people meet their folate needs.', 'Folic acid is safe at the levels used to fortify foods; it is especially important before and during early pregnancy.', 'low', array[]::text[], array[]::text[], array['fortified flour', 'breakfast cereals', 'bread']::text[], '[{"name": "WHO guidelines on food fortification with micronutrients", "url": "https://www.who.int/publications/i/item/9241594012"}, {"name": "EFSA Dietary Reference Values for nutrients", "url": "https://www.efsa.europa.eu/en/topics/topic/dietary-reference-values"}]'::jsonb, 'high', '2026-07', '1.1'),
  ('en:fructose', array['Fructose', 'Fruit sugar']::text[], 'A simple sugar found naturally in fruit and honey.', 'Adds sweetness.', 'Fructose is a form of sugar; the WHO advice on limiting free sugars applies to it when it is added to foods.', 'low', array['people managing diabetes may want to watch total sugars']::text[], array[]::text[], array['soft drinks', 'sweets', 'baked goods', 'sauces']::text[], '[{"name": "WHO guideline: sugars intake for adults and children, 2015", "url": "https://www.who.int/publications/i/item/9789241549028"}, {"name": "USDA FoodData Central", "url": "https://fdc.nal.usda.gov/"}]'::jsonb, 'high', '2026-07', '1.1'),
  ('en:gelatin', array['Gelatin', 'Gelatine']::text[], 'A protein set from animal collagen.', 'Sets and thickens foods into a gel.', 'Gelatin is a safe, common food ingredient; it comes from animals, so it is not suitable for vegetarians or vegans.', 'low', array['vegetarians and vegans, because it is an animal product']::text[], array[]::text[], array['jelly', 'gummy sweets', 'desserts', 'some yogurts']::text[], '[{"name": "USDA FoodData Central", "url": "https://fdc.nal.usda.gov/"}]'::jsonb, 'high', '2026-07', '1.1'),
  ('en:glucose-syrup', array['Glucose syrup', 'Glucose-fructose syrup', 'Corn syrup']::text[], 'A liquid sugar made from starch, such as maize or wheat.', 'Adds sweetness, texture, and shelf life and stops crystals forming.', 'Glucose syrup is a form of sugar; the WHO advice on limiting free sugars applies to it.', 'low', array['people managing diabetes may want to watch total sugars']::text[], array[]::text[], array['sweets', 'soft drinks', 'baked goods', 'ice cream']::text[], '[{"name": "WHO guideline: sugars intake for adults and children, 2015", "url": "https://www.who.int/publications/i/item/9789241549028"}, {"name": "USDA FoodData Central", "url": "https://fdc.nal.usda.gov/"}]'::jsonb, 'high', '2026-07', '1.1'),
  ('en:high-fructose-corn-syrup', array['High-fructose corn syrup', 'HFCS', 'High fructose corn syrup']::text[], 'A liquid sweetener made from corn starch with some glucose converted to fructose.', 'A cheap liquid sweetener that adds sweetness and shelf life, common in drinks.', 'It is a form of sugar; the WHO advice on limiting free sugars applies to it as to other sugars.', 'low', array['people managing diabetes may want to watch total sugars']::text[], array['The evidence treats it much like other added sugars; the concern is total added sugar, not this syrup uniquely']::text[], array['soft drinks', 'sweets', 'sauces', 'baked goods']::text[], '[{"name": "WHO guideline: sugars intake for adults and children, 2015", "url": "https://www.who.int/publications/i/item/9789241549028"}, {"name": "USDA FoodData Central", "url": "https://fdc.nal.usda.gov/"}]'::jsonb, 'high', '2026-07', '1.1'),
  ('en:honey', array['Honey']::text[], 'A natural sweetener made by bees.', 'Adds sweetness and flavour.', 'Honey is a form of sugar and safe for most people; it should not be given to infants under 12 months.', 'low', array['infants under 12 months', 'people managing diabetes may want to watch total sugars']::text[], array['Honey is still a sugar nutritionally, even though it is less processed than table sugar']::text[], array['cereals', 'spreads', 'drinks', 'baked goods']::text[], '[{"name": "USDA FoodData Central", "url": "https://fdc.nal.usda.gov/"}]'::jsonb, 'high', '2026-07', '1.1'),
  ('en:iron', array['Iron', 'Ferrous fumarate', 'Ferrous sulphate', 'Reduced iron']::text[], 'A mineral added to fortify foods.', 'Fortifies foods to help people meet their iron needs.', 'Added iron is safe at the levels used to fortify foods; iron is an essential mineral.', 'low', array[]::text[], array[]::text[], array['fortified cereals', 'fortified flour', 'plant drinks']::text[], '[{"name": "WHO guidelines on food fortification with micronutrients", "url": "https://www.who.int/publications/i/item/9241594012"}, {"name": "USDA FoodData Central", "url": "https://fdc.nal.usda.gov/"}]'::jsonb, 'high', '2026-07', '1.1'),
  ('en:maize', array['Maize', 'Corn', 'Sweetcorn']::text[], 'A cereal grain (corn).', 'A staple grain eaten whole or milled and used as a base for many foods.', 'Maize (corn) is a safe, widely eaten grain.', 'low', array[]::text[], array[]::text[], array['cereals', 'snacks', 'tortillas', 'canned vegetables']::text[], '[{"name": "USDA FoodData Central", "url": "https://fdc.nal.usda.gov/"}]'::jsonb, 'high', '2026-07', '1.1'),
  ('en:maize-starch', array['Maize starch', 'Corn starch', 'Cornflour']::text[], 'Starch extracted from maize (corn).', 'Thickens sauces and adds structure or a light texture.', 'Maize starch is a safe, common food ingredient.', 'low', array[]::text[], array[]::text[], array['sauces', 'soups', 'baked goods', 'custards']::text[], '[{"name": "USDA FoodData Central", "url": "https://fdc.nal.usda.gov/"}]'::jsonb, 'high', '2026-07', '1.1'),
  ('en:maltodextrin', array['Maltodextrin']::text[], 'A carbohydrate made from starch such as maize or wheat.', 'Adds bulk or texture, carries flavours, and gives quick energy.', 'Maltodextrin is a safe, common food ingredient; it raises blood glucose quickly, like other starches and sugars.', 'low', array['people managing diabetes may want to note it affects blood glucose']::text[], array[]::text[], array['sports foods', 'sauces', 'snacks', 'processed foods']::text[], '[{"name": "USDA FoodData Central", "url": "https://fdc.nal.usda.gov/"}]'::jsonb, 'high', '2026-07', '1.1'),
  ('en:milk', array['Milk', 'Cow''s milk']::text[], 'Dairy milk.', 'Adds flavour, protein, and richness.', 'Milk is a safe, nutritious food for most people; it is a common allergen and contains lactose.', 'low', array['people with a milk allergy', 'people with lactose intolerance']::text[], array[]::text[], array['dairy products', 'baked goods', 'chocolate', 'drinks']::text[], '[{"name": "USDA FoodData Central", "url": "https://fdc.nal.usda.gov/"}]'::jsonb, 'high', '2026-07', '1.1'),
  ('en:modified-starch', array['Modified starch', 'Modified corn starch', 'Modified maize starch', 'Food starch modified']::text[], 'A starch that has been physically or chemically treated.', 'Thickens or stabilises foods and stays stable during cooking, freezing, or storage.', 'Modified starches are safe, common food ingredients; EFSA re-evaluated them and found no safety concern at reported uses.', 'low', array[]::text[], array['''Modified'' here means the starch was processed to work better in food, not that it is genetically modified']::text[], array['sauces', 'soups', 'ready meals', 'desserts']::text[], '[{"name": "EFSA re-evaluation of modified starches as food additives", "url": "https://www.efsa.europa.eu/en/topics/topic/food-additives"}, {"name": "USDA FoodData Central", "url": "https://fdc.nal.usda.gov/"}]'::jsonb, 'high', '2026-07', '1.1'),
  ('en:molasses', array['Molasses', 'Treacle', 'Blackstrap molasses']::text[], 'A thick syrup left from refining sugar.', 'Adds sweetness, colour, and a strong flavour.', 'Molasses is a form of sugar; the WHO advice on limiting free sugars applies to it.', 'low', array['people managing diabetes may want to watch total sugars']::text[], array[]::text[], array['baked goods', 'sauces', 'cereals', 'confectionery']::text[], '[{"name": "WHO guideline: sugars intake for adults and children, 2015", "url": "https://www.who.int/publications/i/item/9789241549028"}, {"name": "USDA FoodData Central", "url": "https://fdc.nal.usda.gov/"}]'::jsonb, 'high', '2026-07', '1.1'),
  ('en:natural-flavouring', array['Natural flavouring', 'Natural flavour', 'Flavouring', 'Flavour', 'Flavourings']::text[], 'Flavour ingredients used in small amounts to give or boost taste.', 'Adds or rounds out the taste of a food.', 'Flavourings are used in very small amounts and are regulated for safety; their specific identities are often not listed on the label.', 'low', array[]::text[], array['''Natural flavouring'' means the flavour comes from a natural source; it does not tell you the exact ingredient']::text[], array['soft drinks', 'snacks', 'dairy', 'many processed foods']::text[], '[{"name": "EFSA information on food flavourings", "url": "https://www.efsa.europa.eu/en/topics/topic/flavourings"}]'::jsonb, 'high', '2026-07', '1.1'),
  ('en:niacin', array['Niacin', 'Vitamin B3', 'Nicotinamide']::text[], 'A B vitamin added to foods.', 'Fortifies foods to help people meet their niacin needs.', 'Niacin is safe at the levels used to fortify foods; it is an essential B vitamin.', 'low', array[]::text[], array[]::text[], array['fortified flour', 'breakfast cereals', 'bread']::text[], '[{"name": "EFSA Dietary Reference Values for nutrients", "url": "https://www.efsa.europa.eu/en/topics/topic/dietary-reference-values"}, {"name": "USDA FoodData Central", "url": "https://fdc.nal.usda.gov/"}]'::jsonb, 'high', '2026-07', '1.1'),
  ('en:oat', array['Oats', 'Oat', 'Oat flakes']::text[], 'A cereal grain, often rolled into flakes.', 'A staple grain used in cereals and baking; a source of fibre.', 'Oats are a safe whole grain and a source of dietary fibre.', 'low', array['some people with coeliac disease react to oats unless they are certified gluten-free']::text[], array[]::text[], array['porridge', 'cereals', 'flapjacks', 'baked goods']::text[], '[{"name": "USDA FoodData Central", "url": "https://fdc.nal.usda.gov/"}]'::jsonb, 'high', '2026-07', '1.1'),
  ('en:olive-oil', array['Olive oil']::text[], 'An oil pressed from olives.', 'Used for cooking and dressings and for its flavour.', 'Olive oil is safe to eat and is rich in unsaturated fat.', 'low', array[]::text[], array[]::text[], array['dressings', 'Mediterranean dishes', 'spreads', 'cooking oils']::text[], '[{"name": "USDA FoodData Central", "url": "https://fdc.nal.usda.gov/"}]'::jsonb, 'high', '2026-07', '1.1'),
  ('en:palm-oil', array['Palm oil', 'Palm fat']::text[], 'A vegetable oil pressed from the fruit of the oil palm.', 'Gives a smooth texture and long shelf life and stays solid at room temperature.', 'Palm oil is safe to eat; it is high in saturated fat, which health bodies suggest limiting to support heart health.', 'low', array['people advised to limit saturated fat']::text[], array['Concerns about palm oil centre on saturated fat and the environment, not on it being unsafe to eat']::text[], array['spreads', 'chocolate', 'baked goods', 'margarine']::text[], '[{"name": "WHO guideline: saturated and trans-fatty acid intake, 2023", "url": "https://www.who.int/publications/i/item/9789240073630"}, {"name": "USDA FoodData Central", "url": "https://fdc.nal.usda.gov/"}]'::jsonb, 'high', '2026-07', '1.1'),
  ('en:pea-protein', array['Pea protein', 'Pea protein isolate']::text[], 'Protein extracted from peas.', 'Adds protein and structure, often in plant-based foods.', 'Pea protein is a safe, plant-based protein.', 'low', array[]::text[], array[]::text[], array['meat alternatives', 'plant drinks', 'protein products', 'cereal bars']::text[], '[{"name": "USDA FoodData Central", "url": "https://fdc.nal.usda.gov/"}]'::jsonb, 'high', '2026-07', '1.1'),
  ('en:potato-starch', array['Potato starch']::text[], 'Starch extracted from potatoes.', 'Thickens and binds and adds a light texture.', 'Potato starch is a safe, common food ingredient.', 'low', array[]::text[], array[]::text[], array['sauces', 'baked goods', 'gluten-free foods', 'soups']::text[], '[{"name": "USDA FoodData Central", "url": "https://fdc.nal.usda.gov/"}]'::jsonb, 'high', '2026-07', '1.1'),
  ('en:rapeseed-oil', array['Rapeseed oil', 'Canola oil']::text[], 'A vegetable oil pressed from rapeseed (canola).', 'A neutral cooking oil used for frying, baking, and dressings.', 'Rapeseed (canola) oil is safe to eat and is low in saturated fat.', 'low', array[]::text[], array[]::text[], array['cooking oils', 'spreads', 'baked goods', 'mayonnaise']::text[], '[{"name": "USDA FoodData Central", "url": "https://fdc.nal.usda.gov/"}]'::jsonb, 'high', '2026-07', '1.1'),
  ('en:rice', array['Rice', 'Rice flour']::text[], 'A cereal grain, sometimes milled into flour.', 'A staple carbohydrate; rice flour adds structure in gluten-free foods.', 'Rice is a safe, widely eaten staple grain.', 'low', array[]::text[], array[]::text[], array['rice dishes', 'gluten-free foods', 'cereals', 'snacks']::text[], '[{"name": "USDA FoodData Central", "url": "https://fdc.nal.usda.gov/"}]'::jsonb, 'high', '2026-07', '1.1'),
  ('en:rye', array['Rye', 'Rye flour']::text[], 'A cereal grain, often milled into flour.', 'Used in breads and crispbreads.', 'Rye is a safe whole grain; it contains gluten.', 'low', array['people with coeliac disease or who avoid gluten']::text[], array[]::text[], array['rye bread', 'crispbread', 'cereals']::text[], '[{"name": "USDA FoodData Central", "url": "https://fdc.nal.usda.gov/"}]'::jsonb, 'high', '2026-07', '1.1'),
  ('en:salt', array['Salt', 'Sodium chloride']::text[], 'Sodium chloride — the mineral we know as table salt.', 'Adds flavour and, in many foods, helps preserve them and shape texture.', 'Salt is safe, but most people eat more sodium than health bodies suggest; the WHO recommends limiting sodium to help manage blood pressure.', 'low', array['people advised to limit sodium, for example for high blood pressure']::text[], array['Sea salt and pink salt are still mostly sodium chloride, like ordinary table salt']::text[], array['most savoury packaged foods', 'bread', 'snacks', 'sauces']::text[], '[{"name": "WHO guideline: sodium intake for adults and children, 2012", "url": "https://www.who.int/publications/i/item/9789241504836"}]'::jsonb, 'high', '2026-07', '1.1'),
  ('en:skimmed-milk-powder', array['Skimmed milk powder', 'Skim milk powder', 'Nonfat dry milk']::text[], 'Milk with the fat and water removed, dried to a powder.', 'Adds dairy solids, protein, and body without adding liquid.', 'Skimmed milk powder is safe for most people; it is a milk product and a common allergen.', 'low', array['people with a milk allergy', 'people with lactose intolerance']::text[], array[]::text[], array['chocolate', 'baked goods', 'ready meals', 'beverages']::text[], '[{"name": "USDA FoodData Central", "url": "https://fdc.nal.usda.gov/"}]'::jsonb, 'high', '2026-07', '1.1'),
  ('en:soy-protein', array['Soy protein', 'Soya protein', 'Soy protein isolate', 'Soya protein isolate']::text[], 'Protein extracted from soybeans.', 'Adds protein and structure, often in meat alternatives.', 'Soy protein is safe for most people; it is a common allergen.', 'low', array['people with a soya allergy']::text[], array[]::text[], array['meat alternatives', 'protein products', 'processed foods', 'cereal bars']::text[], '[{"name": "USDA FoodData Central", "url": "https://fdc.nal.usda.gov/"}]'::jsonb, 'high', '2026-07', '1.1'),
  ('en:soybean', array['Soy', 'Soya', 'Soybeans', 'Soya beans']::text[], 'A legume (soybean) and foods made from it.', 'A plant protein used whole or as an ingredient in many foods.', 'Soy is a safe, protein-rich food for most people; it is a common allergen.', 'low', array['people with a soya allergy']::text[], array[]::text[], array['tofu', 'plant drinks', 'meat alternatives', 'processed foods']::text[], '[{"name": "USDA FoodData Central", "url": "https://fdc.nal.usda.gov/"}]'::jsonb, 'high', '2026-07', '1.1'),
  ('en:soybean-oil', array['Soybean oil', 'Soya oil', 'Soya bean oil']::text[], 'A vegetable oil pressed from soybeans.', 'A neutral cooking oil used for frying, baking, and dressings.', 'Soybean oil is safe to eat and is mostly unsaturated fat.', 'low', array['people with a soya allergy may want to check with a clinician, though refined soybean oil is usually tolerated']::text[], array[]::text[], array['cooking oils', 'dressings', 'spreads', 'processed foods']::text[], '[{"name": "USDA FoodData Central", "url": "https://fdc.nal.usda.gov/"}]'::jsonb, 'high', '2026-07', '1.1'),
  ('en:sugar', array['Sugar', 'Sucrose']::text[], 'Sugar (mostly sucrose) that adds sweetness and energy.', 'Adds sweetness and bulk, helps browning, and can help preserve foods like jam.', 'Sugar is safe as a food; the WHO suggests keeping free sugars below 10% of daily energy, and ideally 5%, mainly to protect teeth and help manage weight.', 'low', array['people managing diabetes may want to watch total sugars']::text[], array['The health guidance is about how much sugar we eat, not that any sugar is harmful in itself']::text[], array['soft drinks', 'sweets', 'baked goods', 'cereals']::text[], '[{"name": "WHO guideline: sugars intake for adults and children, 2015", "url": "https://www.who.int/publications/i/item/9789241549028"}, {"name": "USDA FoodData Central", "url": "https://fdc.nal.usda.gov/"}]'::jsonb, 'high', '2026-07', '1.1'),
  ('en:sunflower-oil', array['Sunflower oil', 'Sunflower seed oil']::text[], 'A vegetable oil pressed from sunflower seeds.', 'Used for frying, texture, and as a neutral-tasting fat.', 'Sunflower oil is safe to eat and is mostly unsaturated fat.', 'low', array[]::text[], array[]::text[], array['fried foods', 'spreads', 'dressings', 'snacks']::text[], '[{"name": "USDA FoodData Central", "url": "https://fdc.nal.usda.gov/"}]'::jsonb, 'high', '2026-07', '1.1'),
  ('en:tomato-paste', array['Tomato paste', 'Tomato purée', 'Tomato puree', 'Concentrated tomato']::text[], 'Tomatoes cooked down and concentrated.', 'Adds tomato flavour, colour, and body.', 'Tomato paste is a safe food made from tomatoes.', 'low', array[]::text[], array[]::text[], array['sauces', 'soups', 'pizza', 'ready meals']::text[], '[{"name": "USDA FoodData Central", "url": "https://fdc.nal.usda.gov/"}]'::jsonb, 'high', '2026-07', '1.1'),
  ('en:vinegar', array['Vinegar', 'Spirit vinegar', 'White vinegar']::text[], 'A sour liquid made by fermenting alcohol into acetic acid.', 'Adds a tart flavour and helps preserve foods like pickles.', 'Vinegar is a safe, common food ingredient.', 'low', array[]::text[], array[]::text[], array['dressings', 'sauces', 'pickles', 'condiments']::text[], '[{"name": "USDA FoodData Central", "url": "https://fdc.nal.usda.gov/"}]'::jsonb, 'high', '2026-07', '1.1'),
  ('en:vitamin-c', array['Vitamin C', 'L-ascorbic acid', 'Ascorbic acid (added)']::text[], 'A vitamin added to foods, also used as an antioxidant.', 'Fortifies foods and protects colour and flavour.', 'Vitamin C is safe at the levels used in foods; it is an essential vitamin.', 'low', array[]::text[], array['As an added antioxidant it can appear on labels as E300; it is the same vitamin C']::text[], array['fortified drinks', 'cereals', 'juices']::text[], '[{"name": "EFSA Dietary Reference Values for nutrients", "url": "https://www.efsa.europa.eu/en/topics/topic/dietary-reference-values"}, {"name": "USDA FoodData Central", "url": "https://fdc.nal.usda.gov/"}]'::jsonb, 'high', '2026-07', '1.1'),
  ('en:vitamin-d', array['Vitamin D', 'Vitamin D3', 'Cholecalciferol']::text[], 'A vitamin added to fortify some foods.', 'Fortifies foods such as spreads and cereals with vitamin D.', 'Vitamin D is safe at the levels used to fortify foods; it supports bone health.', 'low', array[]::text[], array[]::text[], array['fortified spreads', 'breakfast cereals', 'plant drinks']::text[], '[{"name": "EFSA Dietary Reference Values for nutrients", "url": "https://www.efsa.europa.eu/en/topics/topic/dietary-reference-values"}, {"name": "USDA FoodData Central", "url": "https://fdc.nal.usda.gov/"}]'::jsonb, 'high', '2026-07', '1.1'),
  ('en:water', array['Water', 'Aqua']::text[], 'Plain water.', 'Acts as a base or carrier and adjusts consistency.', 'Water is an essential nutrient with no intake concern in food.', 'low', array[]::text[], array[]::text[], array['drinks', 'soups', 'sauces', 'many processed foods']::text[], '[{"name": "USDA FoodData Central", "url": "https://fdc.nal.usda.gov/"}]'::jsonb, 'high', '2026-07', '1.1'),
  ('en:wheat-flour', array['Wheat flour', 'Flour', 'Wheat']::text[], 'Flour milled from wheat grain.', 'Forms the structure of breads, baked goods, and batters.', 'Wheat flour is safe for most people; it contains gluten and is a common allergen.', 'low', array['people with coeliac disease or a wheat allergy', 'people avoiding gluten']::text[], array[]::text[], array['bread', 'pasta', 'baked goods', 'batters']::text[], '[{"name": "USDA FoodData Central", "url": "https://fdc.nal.usda.gov/"}]'::jsonb, 'high', '2026-07', '1.1'),
  ('en:whey', array['Whey', 'Whey powder', 'Whey protein']::text[], 'The protein-rich liquid left when milk is made into cheese, often dried.', 'Adds protein, flavour, and texture.', 'Whey is safe for most people; it is a milk product and a common allergen.', 'low', array['people with a milk allergy']::text[], array[]::text[], array['chocolate', 'baked goods', 'protein products', 'processed foods']::text[], '[{"name": "USDA FoodData Central", "url": "https://fdc.nal.usda.gov/"}]'::jsonb, 'high', '2026-07', '1.1'),
  ('en:yeast', array['Yeast', 'Baker''s yeast']::text[], 'A microorganism used to leaven bread and in fermentation.', 'Makes dough rise and adds flavour.', 'Baker''s yeast is a safe, common food ingredient.', 'low', array[]::text[], array[]::text[], array['bread', 'baked goods', 'spreads', 'fermented foods']::text[], '[{"name": "USDA FoodData Central", "url": "https://fdc.nal.usda.gov/"}]'::jsonb, 'high', '2026-07', '1.1'),
  ('en:yogurt', array['Yogurt', 'Yoghurt']::text[], 'A dairy food made by fermenting milk.', 'Adds flavour, protein, and a creamy texture.', 'Yogurt is a safe, nutritious dairy food for most people; it is a milk product.', 'low', array['people with a milk allergy']::text[], array[]::text[], array['dairy aisle', 'desserts', 'drinks', 'dips']::text[], '[{"name": "USDA FoodData Central", "url": "https://fdc.nal.usda.gov/"}]'::jsonb, 'high', '2026-07', '1.1')
